import numpy as np

def check_solution(k, m):
    # We seek x1 in (k, k+1) such that x2 = x1**(k/m) is in (m, m+1)

    # Lower bound for x2: m
    # x1**(k/m) >= m  =>  x1 >= m**(m/k)
    x1_lower_req = m**(m/k)

    # Upper bound for x2: m+1
    # x1**(k/m) < m+1 => x1 < (m+1)**(m/k)
    x1_upper_req = (m + 1)**(m/k)

    # The required interval for x1 is [max(k, x1_lower_req), min(k+1, x1_upper_req))

    L = max(k, x1_lower_req)
    R = min(k + 1, x1_upper_req)

    if L < R:
        # A non-empty intersection exists, hence a valid range for x1.
        return True, L, R
    else:
        return False, None, None

K_range = range(1, 11)
M_range = range(1, 11)

solutions = []
for k in K_range:
    for m in M_range:
        if k == m:
            continue

        found, L, R = check_solution(k, m)

        if found:
            solutions.append((k, m, L, R))

if solutions:
    print("Found solutions (k, m, L_required, R_required):")
    for sol in solutions:
        print(sol)
else:
    print("No solutions found for k, m in [1, 10] where k != m.")

import math

def solve():
    # Construction: a_i = (2/3)^i for i=1, 2, 3
    a = {
        1: (2/3)**1,
        2: (2/3)**2,
        3: (2/3)**3
    }

    print(f"a_1 = {a[1]}")
    print(f"a_2 = {a[2]}")
    print(f"a_3 = {a[3]}")

    # Calculate the required exponents: E_ij = floor(1/a_j)
    exponents = {}
    for j in range(1, 4):
        inv_aj = 1 / a[j]
        E_j = math.floor(inv_aj)
        for i in range(1, 4):
            exponents[(i, j)] = E_j

    print("\nExponents E_ij = floor(1/a_j):")
    for i in range(1, 4):
        for j in range(1, 4):
            print(f"E_{i}{j} = {exponents[(i, j)]}")

    # Check the condition: a_i^E_ij = a_j^E_ji
    all_satisfied = True
    print("\nChecking equation a_i^E_ij = a_j^E_ji for all i, j in {1, 2, 3}:")

    for i in range(1, 4):
        for j in range(1, 4):
            # LHS = a_i ^ E_ij
            LHS = a[i] ** exponents[(i, j)]

            # RHS = a_j ^ E_ji
            RHS = a[j] ** exponents[(j, i)]

            is_equal = abs(LHS - RHS) < 1e-9

            if not is_equal:
                all_satisfied = False
                print(f"--- FAILED for pair ({i}, {j}) ---")
                print(f"LHS (a_{i}^E_{i}{j}): {LHS}")
                print(f"RHS (a_{j}^E_{j}{i}): {RHS}")
                break

            # Since a_i = (2/3)^i, we expect LHS = (2/3)^(i * E_ij) and RHS = (2/3)^(j * E_ji).
            # For i=1, j=2: E_12 = 2. LHS = (2/3)^(1*2) = 4/9. E_21 = 1. RHS = (2/3)^(2*1) = 4/9. They match.
            if i != j:
                print(f"Pair ({i}, {j}) satisfied.")
        if not all_satisfied:
            break

    if all_satisfied:
        print("\nConclusion: All pairs (i, j) satisfied the equation. n >= 3 is confirmed.")
    else:
        print("\nConclusion: The construction failed for some pairs.")

solve()
